package com.phoenix.business.web;import com.phoenix.business.domain.AuditLog;import com.phoenix.business.repository.AuditLogRepository;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/audit-logs") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('OWNER','ADMIN')") public class AuditController {private final AuditLogRepository repo;@GetMapping public Page<AuditLog> list(@RequestParam(required=false)String user,@RequestParam(required=false)String action,@RequestParam(required=false)String entityType,@RequestParam(required=false)java.time.LocalDate from,@RequestParam(required=false)java.time.LocalDate to,@PageableDefault(size=30,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){java.time.Instant a=from==null?null:from.atStartOfDay(java.time.ZoneOffset.UTC).toInstant(),b=to==null?null:to.plusDays(1).atStartOfDay(java.time.ZoneOffset.UTC).toInstant();return repo.filter(blank(user),blank(action),blank(entityType),a,b,p);}private String blank(String s){return s==null||s.isBlank()?null:s.trim();}}
